arguments.command:
cd /tmp/sv-344ae3d5943b46eea80107496641ac40/symbols && \
# Check dynamic symbols - these are often preserved even in stripped binaries
readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | head -5 && \
echo "---" && \
# Look up our specific addresses using the dynamic symbol table
# Frame #01: 0x222098, #02: 0x222234, #03: 0x19bac0, #06: 0x19bc14
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = ""; best_addr = 0; best_size = 0 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && sym_addr > best_addr) {
        best_addr = sym_addr;
        best_size = sym_size;
        best_name = $8;
      }
    }
    END {
      if (best_name != "") {
        printf "  %s + 0x%x\n", best_name, target - best_addr
      } else {
        print "  (not found)"
      }
    }
  '
done

