arguments.command:
cd /tmp/sv-344ae3d5943b46eea80107496641ac40/symbols && \
# Use the full symbol table from the debug file to resolve addresses
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  readelf -W -s libmonosgen-2.0.so.dbg 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = ""; best_addr = 0 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && sym_addr > best_addr && (sym_size == 0 || sym_addr + sym_size > target)) {
        best_addr = sym_addr;
        best_size = sym_size;
        best_name = $8;
      }
    }
    END {
      if (best_name != "") {
        printf "  %s+0x%x (func at 0x%x, size %d)\n", best_name, target - best_addr, best_addr, best_size
      } else {
        print "  (not found)"
      }
    }
  '
done

